        # Determine masks for self and operand, handle scalar/None cases, apply handle_mask if needed
        from copy import deepcopy
        mask_self = getattr(self, 'mask', None)
        mask_operand = None if operand is None else getattr(operand, 'mask', None)

        # Handle case where operand is scalar
        if hasattr(operand, 'isscalar') and getattr(operand, 'isscalar'):
            mask_operand = None

        # Handle case where mask is missing
        if mask_self is None and mask_operand is None:
            return None
        elif mask_self is None and mask_operand is not None:
            return deepcopy(mask_operand)
        elif operand is None or mask_operand is None:
            return deepcopy(mask_self)
